using Microsoft.AspNetCore.Identity; using Microsoft.IdentityModel.Tokens; using System.IdentityModel.Tokens.Jwt; using System.Security.Claims; using System.Text; using UserService.DTOs; using UserService.Entities; using UserService.Repositories;
namespace UserService.Services;
public interface IUserService { Task<UserDto?> GetByIdAsync(int id); }
public interface IAuthService { Task<UserDto> RegisterAsync(RegisterRequest request); Task<LoginResponse> LoginAsync(LoginRequest request); }
public class UserService(IUserRepository users):IUserService { public async Task<UserDto?> GetByIdAsync(int id){var u=await users.GetByIdAsync(id);return u is null?null:new(u.Id,u.Name,u.Email,u.PhoneNumber,u.Role.Name);} }
public class AuthService(IUserRepository users,IRoleRepository roles,IConfiguration config):IAuthService { readonly PasswordHasher<User> hasher=new(); public async Task<UserDto> RegisterAsync(RegisterRequest r){if(string.IsNullOrWhiteSpace(r.Name)||!r.Email.Contains('@')||string.IsNullOrWhiteSpace(r.PhoneNumber)||string.IsNullOrWhiteSpace(r.Password)||r.Password.Length<8)throw new ArgumentException("Invalid registration details."); if(await users.GetByEmailAsync(r.Email) is not null)throw new InvalidOperationException("Email already exists."); if(await users.GetByPhoneNumberAsync(r.PhoneNumber) is not null)throw new InvalidOperationException("Phone number already exists."); var passenger=await roles.GetByNameAsync("Passenger")??throw new InvalidOperationException("Passenger role is missing."); var u=new User{Name=r.Name,Email=r.Email,PhoneNumber=r.PhoneNumber,RoleId=passenger.Id,Role=passenger,CreatedAt=DateTime.UtcNow}; u.PasswordHash=hasher.HashPassword(u,r.Password); await users.AddAsync(u);return new(u.Id,u.Name,u.Email,u.PhoneNumber,passenger.Name);} public async Task<LoginResponse> LoginAsync(LoginRequest r){var u=await users.GetByEmailAsync(r.Email)??throw new UnauthorizedAccessException("Invalid credentials."); if(hasher.VerifyHashedPassword(u,u.PasswordHash,r.Password)==PasswordVerificationResult.Failed)throw new UnauthorizedAccessException("Invalid credentials."); var expires=config.GetValue("Jwt:ExpiresInMinutes",60);var signingKey=config["Jwt:Key"];if(string.IsNullOrWhiteSpace(signingKey))throw new InvalidOperationException("JWT key is not configured.");var key=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(signingKey));var token=new JwtSecurityToken(config["Jwt:Issuer"],config["Jwt:Audience"],[new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Role,u.Role.Name)],expires:DateTime.UtcNow.AddMinutes(expires),signingCredentials:new(key,SecurityAlgorithms.HmacSha256));return new(new JwtSecurityTokenHandler().WriteToken(token),u.Id,u.Role.Name,expires*60);} }
